<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { apiSeguridad } from '@/utils/seguridad'
const users=ref<any[]>([]),roles=ref<any[]>([]),error=ref('')
const cargar=async()=>{try{[users.value,roles.value]=await Promise.all([apiSeguridad('/usuarios'),apiSeguridad('/roles')])}catch(e:any){error.value=e.message}}
onMounted(cargar)
</script>
<template><div class="admin-page"><section class="page-hero admin-hero d-flex align-center justify-space-between ga-4 mb-6"><div class="d-flex align-center ga-4"><VAvatar color="primary" variant="tonal" rounded size="58"><VIcon icon="tabler-users" size="30"/></VAvatar><div><div class="process-kicker">Seguridad y acceso</div><h1 class="text-h4 font-weight-bold mb-1">Usuarios</h1><p class="text-medium-emphasis mb-0">Cuentas habilitadas dentro de la organización.</p></div></div><VChip color="primary" variant="tonal" size="large">{{users.length}} usuarios</VChip></section><VCard class="module-card"><VCardItem class="module-header"><VCardTitle><VIcon icon="tabler-address-book" class="me-2"/>Directorio de usuarios</VCardTitle><VCardSubtitle>Empresa, departamento y nivel de acceso asignado</VCardSubtitle></VCardItem><VCardText class="pa-6"><VAlert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</VAlert><VDataTable :items="users" :headers="[{title:'Nombre',key:'nombre_completo'},{title:'Correo',key:'email'},{title:'Empresa',key:'empresa_id'},{title:'Departamento',key:'departamento'},{title:'Rol',key:'rol'}]" class="product-table"><template #item.nombre_completo="{item}"><div class="d-flex align-center ga-2 py-2"><VAvatar color="primary" variant="tonal" size="34"><VIcon icon="tabler-user" size="18"/></VAvatar><strong>{{item.nombre_completo}}</strong></div></template><template #item.empresa_id="{item}"><VChip size="small" variant="tonal">{{item.empresa_id||'Sin asignar'}}</VChip></template><template #item.departamento="{item}">{{item.departamento||'Sin asignar'}}</template><template #item.rol="{item}"><VChip size="small" color="primary" variant="tonal">{{item.rol}}</VChip></template><template #no-data><div class="process-empty py-10"><VIcon icon="tabler-users-off" size="44"/><strong>No hay usuarios disponibles</strong></div></template></VDataTable></VCardText></VCard></div></template>
